package com.smeal.exception; import com.smeal.dto.ErrorDTO;import jakarta.servlet.http.HttpServletRequest;import java.time.Instant;import java.util.NoSuchElementException;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class GlobalExceptionHandler {@ExceptionHandler({NoSuchElementException.class,ResourceNotFoundException.class})ResponseEntity<ErrorDTO> missing(Exception e,HttpServletRequest r){return error(404,e,r);}@ExceptionHandler(UnauthorizedException.class)ResponseEntity<ErrorDTO> unauthorized(Exception e,HttpServletRequest r){return error(401,e,r);}@ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class})ResponseEntity<ErrorDTO> bad(Exception e,HttpServletRequest r){return error(400,e,r);}@ExceptionHandler({IllegalStateException.class,MLServiceException.class})ResponseEntity<ErrorDTO> unavailable(Exception e,HttpServletRequest r){return error(503,e,r);}@ExceptionHandler(Exception.class)ResponseEntity<ErrorDTO> other(Exception e,HttpServletRequest r){return error(500,e,r);}private ResponseEntity<ErrorDTO> error(int status,Exception e,HttpServletRequest r){String msg=e instanceof MethodArgumentNotValidException?"Request validation failed":e.getMessage();return ResponseEntity.status(status).body(new ErrorDTO(Instant.now(),status,msg,r.getRequestURI()));}}
